#include <iostream>
#include <cmath>
using namespace std;

int main() {
    int f(int x) {
        return 3 * x * x - 2;
    }

    int g(int x) {
        return x * x + x + 1;
    }

    int sum = 0;
    for (int i = 0; i <= 25; i++) {
        int value = g(f(i));
        if (value <= 25) {
            sum += value;
        }
    }
    cout << "The sum of all possible values of g(25) is: " << sum << endl;
    return 0;
}

