#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    // Define the polynomial
    vector<int> polynomial = {1, -2, -5, 6};

    // Find the roots of the polynomial
    vector<int> roots;
    for (int i = 0; i < polynomial.size(); i++) {
        if (polynomial[i] == 0) {
            roots.push_back(i);
        }
    }

    // Check if the polynomial has repeated roots
    if (roots.size() > 1) {
        cout << "The polynomial has repeated roots." << endl;
        return 0;
    }

    // Find the partial fraction decomposition
    vector<int> partial_fractions;
    for (int i = 0; i < roots.size(); i++) {
        partial_fractions.push_back(polynomial[roots[i]]);
    }

    // Calculate the product of the partial fractions
    int product = 1;
    for (int i = 0; i < partial_fractions.size(); i++) {
        product *= partial_fractions[i];
    }

    // Print the product
    cout << "The product of the partial fractions is: " << product << endl;

    return 0;
}

